## 3. Result-Generation Logic (form data → recommendation)

Source: `client/src/lib/parkinsonsLogic.ts`

```typescript
/**
 * Parkinson's Disease Clinical Logic Engine
 * Based on: MDS 2025 Evidence-Based Medicine Review, AAN 2023 Practice Guidelines,
 *            MDS-UPDRS staging, DBS candidacy criteria
 * Key decisions: Initial therapy selection, motor fluctuation management, DBS candidacy,
 *                non-motor symptom management, disease-modifying therapy (neuroprotection)
 */

export type PDStage = 'early' | 'moderate' | 'advanced';
export type MotorFluctuations = 'none' | 'wearing_off' | 'on_off' | 'dyskinesia' | 'freezing';
export type InitialTherapyHistory =
  | 'none'
  | 'on_levodopa'
  | 'on_dopamine_agonist'
  | 'on_mao_b_inhibitor'
  | 'on_combination';
export type TremorDominant = boolean;

export interface ParkinsonsInput {
  stage: PDStage;
  age: number;
  updrsMotorScore: number; // MDS-UPDRS Part III, 0–132
  hoehnYahrScale: number; // 1–5
  motorFluctuations: MotorFluctuations;
  initialTherapyHistory: InitialTherapyHistory;
  tremorDominant: TremorDominant;
  hasHallucinations: boolean;
  hasDementia: boolean; // MMSE <24 or MoCA <21
  hasOrthostasis: boolean;
  hasImpulseControlDisorder: boolean; // relevant for dopamine agonists
  hasCardiacHistory: boolean;
  isDBSCandidate: boolean; // clinical assessment
  dbsContraindications: string[]; // e.g., dementia, active psychiatric illness
  wantsNonOralTherapy: boolean;
  isPregnantOrPlanning: boolean;
  levodopaDailyDose?: number; // mg/day, relevant for dyskinesia
  offTimeHoursPerDay?: number; // relevant for fluctuations
}

export interface ParkinsonsRecommendation {
  primaryRecommendation: string;
  pharmacotherapy: string;
  dbsAssessment: string;
  nonMotorManagement: string;
  recommendedAgents: string[];
  agentsToAvoid: string[];
  urgentFlags: string[];
  nextSteps: string[];
  evidenceLevel: 'A' | 'B' | 'C' | 'U';
  rationale: string;
  references: Array<{ citation: string; pmid?: string; url?: string }>;
}

export function assessParkinsons(input: ParkinsonsInput): ParkinsonsRecommendation {
  const urgentFlags: string[] = [];
  const agentsToAvoid: string[] = [];
  const recommendedAgents: string[] = [];
  const nextSteps: string[] = [];

  // Safety flags
  if (input.hasHallucinations) {
    urgentFlags.push('Hallucinations present: avoid dopamine agonists and MAO-B inhibitors if possible; consider clozapine 6.25–50mg or pimavanserin 34mg for psychosis');
    agentsToAvoid.push('Dopamine agonists (worsen psychosis)', 'MAO-B inhibitors (may worsen psychosis)', 'Typical antipsychotics (haloperidol, risperidone — worsen parkinsonism)');
  }
  if (input.hasImpulseControlDisorder) {
    urgentFlags.push('Impulse control disorder: reduce or discontinue dopamine agonist — ICD occurs in 10–15% of patients on agonists');
    agentsToAvoid.push('Dopamine agonists (ICD risk — pramipexole, ropinirole, rotigotine)');
  }
  if (input.hasDementia) {
    agentsToAvoid.push('Anticholinergics (worsen cognition)', 'Amantadine (may worsen confusion)');
    urgentFlags.push('Dementia present: avoid anticholinergics and amantadine; rivastigmine is evidence-based for PD dementia (AAN Level A)');
  }
  if (input.hasOrthostasis) {
    agentsToAvoid.push('High-dose dopamine agonists (worsen orthostasis)');
    urgentFlags.push('Orthostatic hypotension: review all antihypertensives; consider midodrine or droxidopa');
  }

  // DBS assessment
  let dbsAssessment = '';
  const dbsCandidacyCriteria = [
    input.stage === 'moderate' || input.stage === 'advanced',
    input.motorFluctuations !== 'none',
    !input.hasDementia,
    input.dbsContraindications.length === 0,
    input.updrsMotorScore >= 20,
  ];
  const dbsCriteriaMetCount = dbsCandidacyCriteria.filter(Boolean).length;

  if (input.isDBSCandidate && dbsCriteriaMetCount >= 4) {
    dbsAssessment =
      'DBS CANDIDATE: Patient meets criteria for deep brain stimulation evaluation. ' +
      'Refer to multidisciplinary DBS team (neurology, neurosurgery, neuropsychology). ' +
      'STN-DBS is preferred target for motor fluctuations + dyskinesia. ' +
      'GPi-DBS preferred if prominent dyskinesia or psychiatric comorbidity. ' +
      'Levodopa responsiveness (UPDRS improvement ≥30% on/off) is the strongest predictor of DBS benefit.';
    recommendedAgents.push('DBS evaluation referral (STN or GPi target)');
    nextSteps.push('Refer to DBS multidisciplinary team', 'Levodopa challenge test (UPDRS Part III on vs off)', 'Neuropsychological evaluation', 'Psychiatric clearance');
  } else if (input.dbsContraindications.length > 0) {
    dbsAssessment =
      `DBS contraindicated: ${input.dbsContraindications.join(', ')}. ` +
      'Consider levodopa-carbidopa intestinal gel (LCIG/Duopa) or subcutaneous apomorphine infusion as device-aided alternatives.';
    if (input.wantsNonOralTherapy) {
      recommendedAgents.push('Levodopa-carbidopa intestinal gel (LCIG/Duopa)', 'Subcutaneous apomorphine infusion');
    }
  } else {
    dbsAssessment = 'DBS not currently indicated. Optimize pharmacotherapy first. Reassess if motor fluctuations worsen despite optimized medical therapy.';
  }

  // Pharmacotherapy by stage and fluctuations
  let pharmacotherapy = '';

  if (input.stage === 'early' && input.motorFluctuations === 'none') {
    if (input.initialTherapyHistory === 'none') {
      if (input.age < 65 && !input.tremorDominant) {
        pharmacotherapy =
          'Early PD, age <65: dopamine agonist (pramipexole, ropinirole, rotigotine) as initial therapy to delay levodopa initiation and reduce dyskinesia risk. ' +
          'MAO-B inhibitors (rasagiline, selegiline, safinamide) are an alternative for mild symptoms. ' +
          'Levodopa remains most effective — initiate when functional impairment warrants.';
        recommendedAgents.push(
          'Pramipexole ER 0.375–4.5mg/day',
          'Ropinirole XL 2–24mg/day',
          'Rotigotine patch 2–8mg/24h',
          'Rasagiline 1mg/day (MAO-B inhibitor)',
          'Safinamide 50–100mg/day (add-on)'
        );
      } else {
        pharmacotherapy =
          'Early PD, age ≥65 or tremor-dominant: levodopa-carbidopa is preferred initial therapy. ' +
          'Provides best symptomatic control with lowest neuropsychiatric risk in older patients. ' +
          'Start low (25/100mg TID) and titrate to symptom control.';
        recommendedAgents.push(
          'Levodopa-carbidopa 25/100mg TID (titrate to response)',
          'Rasagiline 1mg/day (adjunct for mild symptoms)'
        );
      }
    } else {
      pharmacotherapy =
        'Established early PD on therapy: optimize current regimen. ' +
        'If on MAO-B inhibitor with inadequate control, add levodopa or dopamine agonist. ' +
        'If on dopamine agonist with adequate control, continue and monitor for ICD.';
      recommendedAgents.push('Optimize current therapy', 'Add levodopa if functional impairment persists');
    }
  } else if (input.motorFluctuations === 'wearing_off') {
    pharmacotherapy =
      'Wearing-off fluctuations: multiple strategies available (AAN Level A). ' +
      '1) Increase levodopa dose frequency (shorten dosing interval). ' +
      '2) Add MAO-B inhibitor (rasagiline, safinamide) to extend levodopa effect. ' +
      '3) Add COMT inhibitor (entacapone, opicapone) to extend levodopa half-life. ' +
      '4) Add dopamine agonist as adjunct. ' +
      '5) Consider extended-release carbidopa-levodopa (Rytary) for smoother coverage.';
    recommendedAgents.push(
      'Rasagiline 1mg/day or Safinamide 50–100mg/day (MAO-B inhibitor add-on)',
      'Entacapone 200mg with each levodopa dose (COMT inhibitor)',
      'Opicapone 50mg once daily (COMT inhibitor)',
      'Carbidopa-levodopa ER (Rytary) for smoother coverage',
      'Istradefylline 20–40mg/day (adenosine A2A antagonist — adjunct)'
    );
    nextSteps.push('Wearing-off diary to quantify off-time', 'Adjust levodopa dosing interval before adding adjunct');
  } else if (input.motorFluctuations === 'dyskinesia') {
    pharmacotherapy =
      'Levodopa-induced dyskinesia (LID): ' +
      '1) Reduce individual levodopa dose, increase frequency (same total daily dose). ' +
      '2) Add amantadine (NMDA antagonist) — reduces dyskinesia by 50–60% (AAN Level B). ' +
      '3) Extended-release amantadine (Gocovri 137mg nightly) FDA-approved for LID. ' +
      '4) If refractory: DBS (GPi target preferred for dyskinesia) or LCIG.';
    if (!input.hasDementia) {
      recommendedAgents.push(
        'Amantadine 100mg BID–TID',
        'Amantadine ER (Gocovri) 137mg nightly (FDA-approved for LID)',
        'Reduce levodopa dose + increase frequency'
      );
    }
    recommendedAgents.push('DBS evaluation (GPi target preferred for dyskinesia)');
  } else if (input.motorFluctuations === 'on_off' || input.stage === 'advanced') {
    pharmacotherapy =
      'Advanced PD with on-off fluctuations: device-aided therapy should be considered. ' +
      '1) DBS (STN or GPi) — gold standard for motor fluctuations in appropriate candidates. ' +
      '2) Levodopa-carbidopa intestinal gel (LCIG/Duopa) — continuous duodenal infusion, reduces off-time by 4–6 hours/day. ' +
      '3) Subcutaneous apomorphine infusion — continuous SC pump, effective for on-off fluctuations. ' +
      '4) Subcutaneous levodopa (foslevodopa/foscarbidopa — Produodopa) — emerging SC continuous delivery.';
    recommendedAgents.push(
      'DBS evaluation (STN-DBS preferred for fluctuations)',
      'LCIG (Duopa) — continuous intestinal gel infusion',
      'Subcutaneous apomorphine infusion',
      'Apomorphine SC injection (Apokyn) for rescue during off episodes'
    );
    nextSteps.push('Refer to movement disorder specialist', 'DBS multidisciplinary evaluation', 'Off-time diary (hours/day)');
  } else if (input.motorFluctuations === 'freezing') {
    pharmacotherapy =
      'Freezing of gait (FOG): optimize levodopa timing (often occurs during off-state). ' +
      'Physical therapy with cueing strategies (auditory, visual). ' +
      'Avoid anticholinergics. DBS may improve FOG in some patients (less predictable than other motor symptoms).';
    recommendedAgents.push('Optimize levodopa timing', 'Physical therapy with cueing', 'DBS evaluation if refractory');
    agentsToAvoid.push('Anticholinergics (may worsen FOG and cognition)');
  } else {
    pharmacotherapy =
      'Moderate PD: optimize levodopa regimen. Consider adjunct therapy if wearing-off develops. ' +
      'Regular reassessment every 3–6 months.';
    recommendedAgents.push('Optimize levodopa-carbidopa regimen', 'Consider MAO-B or COMT inhibitor adjunct');
  }

  // Non-motor management
  let nonMotorManagement =
    'Non-motor symptom management is essential in PD: ' +
    'Depression/anxiety: SSRIs (paroxetine, sertraline) or SNRIs. ' +
    'Dementia: rivastigmine (AAN Level A). ' +
    'Psychosis: pimavanserin 34mg/day (FDA-approved for PD psychosis) or low-dose clozapine. ' +
    'REM sleep behavior disorder: clonazepam 0.5–1mg or melatonin 3–12mg nightly. ' +
    'Constipation: polyethylene glycol, lubiprostone. ' +
    'Orthostatic hypotension: midodrine, droxidopa, fludrocortisone. ' +
    'Sialorrhea: botulinum toxin injection to parotid/submandibular glands.';

  if (input.hasDementia) {
    nonMotorManagement += ' Rivastigmine 3–12mg/day (patch or oral) is the only FDA-approved agent for PD dementia.';
    recommendedAgents.push('Rivastigmine for PD dementia (AAN Level A)');
  }

  if (nextSteps.length === 0) {
    nextSteps.push(
      'Movement disorder specialist referral',
      'MDS-UPDRS motor assessment (on and off state)',
      'Neuropsychological screening (MoCA)',
      'Physical, occupational, and speech therapy evaluation',
      'Fall risk assessment',
      'Driving safety evaluation'
    );
  }

  const rationale =
    `PD stage: ${input.stage}. ` +
    `Age: ${input.age}. ` +
    `Hoehn-Yahr: ${input.hoehnYahrScale}. ` +
    `MDS-UPDRS III: ${input.updrsMotorScore}. ` +
    `Motor fluctuations: ${input.motorFluctuations.replace(/_/g, ' ')}. ` +
    `Prior therapy: ${input.initialTherapyHistory.replace(/_/g, ' ')}. ` +
    `Hallucinations: ${input.hasHallucinations ? 'Yes' : 'No'}. ` +
    `Dementia: ${input.hasDementia ? 'Yes' : 'No'}.`;

  return {
    primaryRecommendation:
      input.stage === 'early'
        ? `Early PD: ${input.age < 65 ? 'dopamine agonist or MAO-B inhibitor as initial therapy (age <65)' : 'levodopa-carbidopa preferred (age ≥65)'}. Optimize symptomatic control.`
        : input.motorFluctuations !== 'none'
        ? `${input.stage.charAt(0).toUpperCase() + input.stage.slice(1)} PD with ${input.motorFluctuations.replace(/_/g, ' ')}: adjunct therapy or device-aided therapy indicated.`
        : `${input.stage.charAt(0).toUpperCase() + input.stage.slice(1)} PD: optimize pharmacotherapy and monitor for fluctuations.`,
    pharmacotherapy,
    dbsAssessment,
    nonMotorManagement,
    recommendedAgents,
    agentsToAvoid,
    urgentFlags,
    nextSteps,
    evidenceLevel: 'A',
    rationale,
    references: [
      {
        citation: 'Fox SH, et al. International Parkinson and Movement Disorder Society Evidence-Based Medicine Review: Update on treatments for the motor symptoms of Parkinson\'s disease. Mov Disord. 2018;33(8):1248-1266.',
        pmid: '29570866',
        url: 'https://pubmed.ncbi.nlm.nih.gov/29570866/',
      },
      {
        citation: 'Fasano A, et al. Management of advanced therapies in Parkinson\'s disease patients in times of humanitarian crisis. NPJ Parkinsons Dis. 2020;6:20.',
        pmid: '32665958',
        url: 'https://pubmed.ncbi.nlm.nih.gov/32665958/',
      },
      {
        citation: 'Connolly BS, Lang AE. Pharmacological treatment of Parkinson disease: a review. JAMA. 2014;311(16):1670-1683.',
        pmid: '24756517',
        url: 'https://pubmed.ncbi.nlm.nih.gov/24756517/',
      },
      {
        citation: 'Bhidayasiri R, et al. Evidence-based guideline: Treatment of tardive syndromes. Neurology. 2013;81(5):463-469.',
        pmid: '23897874',
        url: 'https://pubmed.ncbi.nlm.nih.gov/23897874/',
      },
      {
        citation: 'MDS 2025 Evidence-Based Medicine Review: Parkinson\'s Disease. Movement Disorder Society.',
        url: 'https://www.movementdisorders.org/',
      },
      {
        citation: 'Deuschl G, et al. A randomized trial of deep-brain stimulation for Parkinson\'s disease. N Engl J Med. 2006;355(9):896-908.',
        pmid: '16943402',
        url: 'https://pubmed.ncbi.nlm.nih.gov/16943402/',
      },
    ],
  };
}

export function getPDStageColor(stage: PDStage): string {
  switch (stage) {
    case 'early': return 'text-green-700 bg-green-50 border-green-200';
    case 'moderate': return 'text-yellow-700 bg-yellow-50 border-yellow-200';
    case 'advanced': return 'text-red-700 bg-red-50 border-red-200';
  }
}
